{
  "root_cause": "The radios component only updates conditional panels on click events within its own module. Keyboard navigation changes the checked state via arrow keys, firing a change event but not a click. Moreover, the opt-out radio is in a separate module, so its change event does not propagate to the first module, leaving the conditional panel visible.",
  "repair_strategy": "Make each radios module listen for change events on the containing form (or document) for radios sharing the same name. When such a change occurs, update all conditional panels in that module. This ensures conditionals stay in sync regardless of which radio in the group is selected, and regardless of input method.",
  "edits": [
    {
      "path": "src/govuk/components/radios/radios.js",
      "sha256": "a5f3970a55a7d3dd59bfdfb0ef82c8f9f8fd2ace3eefa606ec486fb263e86b8c",
      "before": "Radios.prototype.init = function () {
  var $module = this.$module
  var $inputs = this.$inputs

  /**
  * Loop over all items with [data-controls]
  * Check if they have a matching conditional reveal
  * If they do, assign attributes.
  **/
  nodeListForEach($inputs, function ($input) {
    var controls = $input.getAttribute('data-aria-controls')

    // Check if input controls anything
    // Check if content exists, before setting attributes.
    if (!controls || !$module.querySelector('#' + controls)) {
      return
    }

    // If we have content that is controlled, set attributes.
    $input.setAttribute('aria-controls', controls)
    $input.removeAttribute('data-aria-controls')
    this.setAttributes($input)
  }.bind(this))

  // Handle events
  $module.addEventListener('click', this.handleClick.bind(this))
}",
      "after": "Radios.prototype.init = function () {
  var $module = this.$module
  var $inputs = this.$inputs

  // Find the form to listen for changes on the radio group
  this.$form = $module.closest('form') || document
  // Get the radio group name from the first input (all inputs in a module share the same name)
  this.radioName = $inputs[0] ? $inputs[0].getAttribute('name') : null

  // Collect conditional inputs in this module
  this.$conditionalInputs = []
  nodeListForEach($inputs, function ($input) {
    var controls = $input.getAttribute('data-aria-controls')
    if (!controls || !$module.querySelector('#' + controls)) {
      return
    }
    $input.setAttribute('aria-controls', controls)
    $input.removeAttribute('data-aria-controls')
    this.setAttributes($input)
    this.$conditionalInputs.push($input)
  }.bind(this))

  // Handle events: listen for change on the form for radios in the same group
  if (this.radioName) {
    this.$form.addEventListener('change', this.handleChange.bind(this))
  }
}"
    },
    {
      "path": "src/govuk/components/radios/radios.js",
      "sha256": "a5f3970a55a7d3dd59bfdfb0ef82c8f9f8fd2ace3eefa606ec486fb263e86b8c",
      "before": "Radios.prototype.handleClick = function (event) {
  nodeListForEach(this.$inputs, function ($input) {
    // If a radio with aria-controls, handle click
    var isRadio = $input.getAttribute('type') === 'radio'
    var hasAriaControls = $input.getAttribute('aria-controls')
    if (isRadio && hasAriaControls) {
      this.setAttributes($input)
    }
  }.bind(this))
}

export default Radios",
      "after": "Radios.prototype.handleChange = function (event) {
  var $target = event.target
  // Only react to radio changes in the same group
  if ($target.getAttribute('type') !== 'radio' || $target.getAttribute('name') !== this.radioName) {
    return
  }
  // Update all conditional inputs in this module
  nodeListForEach(this.$conditionalInputs, function ($input) {
    this.setAttributes($input)
  }.bind(this))
}

export default Radios"
    }
  ],
  "expected_accessibility_effect": "Keyboard users can navigate between all radio options in the same group (including across modules) using arrow keys, and conditional fields appear/disappear correctly, satisfying WCAG 2.1.1 (Keyboard) and 2.4.3 (Focus Order).",
  "functional_risks": [
    "Multiple modules on the same form will each attach a change listener; this is safe as they only react to their own radio group name.",
    "If a module contains radios with different names, the behavior may be incorrect, but the component assumes a single group per module.",
    "The change event fires on every radio change, but setAttributes is idempotent."
  ],
  "verification_requirements": [
    "Selecting 'Text message' via ArrowDown shows the mobile number field.",
    "Moving to 'I do not want reminders' via another ArrowDown hides the mobile number field.",
    "Clicking radios with mouse continues to work as before.",
    "Form data reflects the correct selected value after keyboard navigation.",
    "Rapid keyboard navigation does not cause stale states."
  ]
}
